Value.Calculation:
Let ( [

// Same normalizing the widget does: commas, semicolons, returns and spaces all
// separate prefixes; blanks and repeats are dropped; stored as "A, B".
~v = Substitute ( JSONGetElement ( $param ; "TrackingPrefix" ) ; [ ¶ ; "," ] ; [ ";" ; "," ] ; [ Char ( 9 ) ; "," ] ; [ " " ; "," ] ) ;
~l = Substitute ( ~v ; "," ; ¶ )

] ;

Substitute (
	While (
		[ ~i = 1 ; ~o = "" ] ;
		~i ≤ ValueCount ( ~l ) ;
		[
			~p = Trim ( GetValue ( ~l ; ~i ) ) ;
			~o = If ( IsEmpty ( ~p ) or not IsEmpty ( FilterValues ( Upper ( ~o ) ; Upper ( ~p ) ) ) ; ~o ; List ( ~o ; ~p ) ) ;
			~i = ~i + 1
		] ;
		~o
	) ;
	¶ ; ", "
)

)

Let ( [

// Any of these prefixes already on ANOTHER account (exact, case-insensitive)?
// A shorter prefix that only overlaps a longer one is fine - longest match wins.
~mine = Upper ( Substitute ( $prefix ; [ " " ; "" ] ; [ "," ; ¶ ] ) ) ;
~raw = ExecuteSQL ( " select \"TrackingPrefix\", \"Name\" from \"Account\" where \"__ID\" <> ? and \"TrackingPrefix\" is not null " ; Char ( 31 ) ; Char ( 30 ) ; $id ) ;
~ok = not IsEmpty ( ~raw ) and Left ( ~raw ; 1 ) ≠ "?" ;
~rows = Substitute ( ~raw ; [ ¶ ; " " ] ; [ Char ( 30 ) ; ¶ ] ) ;
~n = If ( ~ok and not IsEmpty ( $prefix ) ; ValueCount ( ~rows ) ; 0 )

] ;

While (
	[ ~i = 1 ; ~out = "" ] ;
	~i ≤ ~n ;
	[
		~r = Substitute ( GetValue ( ~rows ; ~i ) ; Char ( 31 ) ; ¶ ) ;
		~theirs = Upper ( Substitute ( GetValue ( ~r ; 1 ) ; [ " " ; "" ] ; [ "," ; ¶ ] ) ) ;
		~hit = GetValue ( FilterValues ( ~mine ; ~theirs ) ; 1 ) ;
		~out = If ( IsEmpty ( ~hit ) ; ~out ; List ( ~out ; ~hit & " is already on " & GetValue ( ~r ; 2 ) ) ) ;
		~i = ~i + 1
	] ;
	Substitute ( ~out ; ¶ ; ". " )
)

)

JSONSetElement ( "" ;
	[ "ok" ; $ok ; JSONBoolean ] ;
	[ "__ID" ; $id ; JSONString ] ;
	[ "TrackingPrefix" ; $prefix ; JSONString ] ;
	[ "errors" ; If ( $ok ; "" ; "The tracking prefix was not saved. " & JSONGetElementValid ( $result ; "error.message" ) ) ; JSONString ]
)
